require_once __DIR__.'/includes/cms.php';require_once __DIR__.'/includes/account-layout.php';cms_db();header('Cache-Control: no-store');$flash=$_SESSION['reset_flash99']??[];unset($_SESSION['reset_flash99']);$error=$flash['error']??'';$notice=$flash['notice']??'';$staff=($_GET['target']??'')==='staff';$kind=$staff?'staff':'participant';$challenge=$_SESSION['reset_'.$kind]??'';
if($_SERVER['REQUEST_METHOD']==='POST')try{
 az_csrf();if(($_POST['action']??'')==='request'){
  if(!az_mail_ready()&&!(getenv('ANAZORI_TEST_MODE')==='1'&&getenv('ANAZORI_TEST_OUTBOX')))throw new RuntimeException('Email delivery is temporarily unavailable. Please contact the organisers.');$email=strtolower(cms_text('email',254));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid email.');az_auth_limit('reset.request',$email,5,3600);
  $s=cms_db()->prepare($staff?'SELECT * FROM users WHERE LOWER(email)=? AND active=1':'SELECT * FROM az_participants WHERE LOWER(email)=? AND active=1');$s->execute([$email]);$u=$s->fetch();
  if($u&&(!$staff||$u['role']!=='SUPERADMIN'||az_is_super($u)))$challenge=az_otp_start('RESET',$kind,(int)$u['id'],$email);else{$challenge=bin2hex(random_bytes(24));$_SESSION['az_challenges'][$challenge]=true;}
  $_SESSION['reset_'.$kind]=$challenge;$notice='If that email belongs to an active account, a code has been sent. Enter it below to choose a new password.';
 }else{
  $password=$_POST['password']??'';if(!is_string($password)||$password!==($_POST['confirm_password']??null))throw new RuntimeException('Passwords must match.');az_password($password);
  az_otp_consume($challenge,cms_text('code',6),'RESET',function($db,$r)use($kind,$password){if($r['user_kind']!==$kind)throw new RuntimeException('Invalid code.');$table=$kind==='staff'?'users':'az_participants';$db->prepare('UPDATE '.$table.' SET password_hash=?,session_version=session_version+1'.($kind==='staff'?',must_change_password=0':'').' WHERE id=? AND active=1')->execute([password_hash($password,PASSWORD_DEFAULT),$r['user_id']]);if($kind==='participant')$db->prepare('DELETE FROM az_remember_tokens102 WHERE participant_id=?')->execute([$r['user_id']]);az_auth_event('password_reset','email_otp',['id'=>$r['user_id']],$kind);});unset($_SESSION['reset_'.$kind]);$challenge='';$notice='Password updated. Sign in with your new password.';
 }
}catch(Throwable $e){$error=$e instanceof PDOException?'Password reset is temporarily unavailable.':$e->getMessage();}
if($_SERVER['REQUEST_METHOD']==='POST'){$_SESSION['reset_flash99']=['error'=>$error,'notice'=>$notice];header('Location: /forgot-password.php'.($staff?'?target=staff':''),true,303);exit;}
